def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = tuple(h[0] for h in history)
    opp = tuple(h[1] for h in history)
    last_my = my[-1]
    last_opp = opp[-1]

    if n >= 99:
        return 'D'

    my_d = sum(1 for x in my if x == 'D')
    opp_d = sum(1 for x in opp if x == 'D')

    if n >= 3 and opp_d == n:
        return 'D'

    if n <= 4:
        return 'C'

    recent = opp[-10:] if n >= 10 else opp
    recent_my = my[-10:] if n >= 10 else my
    opp_recent_d = sum(1 for x in recent if x == 'D')
    my_recent_d = sum(1 for x in recent_my if x == 'D')

    if n >= 6 and sum(1 for x in opp[-6:] if x == 'D') == 6:
        return 'D'

    punish = 0
    forgive = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if opp[i + 1] == 'D':
                punish += 1
            else:
                forgive += 1

    if last_opp == 'D':
        if n >= 2 and opp[-2] == 'D':
            if opp_d * 100 <= 5 * n and my_d > opp_d + 2:
                return 'C'
            return 'D'

        if opp_d * 100 <= 5 * n and opp_recent_d <= 1:
            return 'C'

        if opp_d * 100 <= 15 * n and my_d * 100 <= 20 * n:
            return 'C'

        if opp_d * 100 <= 35 * n:
            return 'D' if rng.random() < 0.5 else 'C'

        if opp_d * 100 <= 60 * n:
            return 'D'

        return 'D' if rng.random() < 0.8 else 'C'

    if punish == 0 and forgive > 0 and opp_d == 0 and my_d > 0:
        return 'D'

    if punish == 0 and forgive >= 2 and opp_d <= 2 and my_d > opp_d + 3 and my_recent_d < 10:
        return 'D'

    if my_d == 0:
        if opp_d == 0 and n >= 25:
            return 'D'
        if opp_d <= 2 and n >= 40:
            return 'D'
        if opp_d == 0 and n >= 80:
            return 'D'

    if my_recent_d >= 12 and opp_d <= 2:
        return 'C'

    return 'C'
